#include <bits/stdc++.h>using namespace std; const int MAX = 1001; long long grid[MAX][MAX];long long pref[MAX][MAX]; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        int n, q;        cin >> n >> q;         // Reset grid        for (int i = 0; i < MAX; i++) {            for (int j = 0; j < MAX; j++) {                grid[i][j] = 0;                pref[i][j] = 0;            }        }         // Fill grid        for (int i = 0; i < n; i++) {            int h, w;            cin >> h >> w;            grid[h][w] += (long long)h * w;        }         // Build prefix sum        for (int i = 1; i < MAX; i++) {            for (int j = 1; j < MAX; j++) {                pref[i][j] = grid[i][j]                           + pref[i-1][j]                           + pref[i][j-1]                           - pref[i-1][j-1];            }        }         // Process queries        while (q--) {            int hs, ws, hb, wb;            cin >> hs >> ws >> hb >> wb;             // strict: (hs+1 to hb-1), (ws+1 to wb-1)            int h1 = hs + 1;            int w1 = ws + 1;            int h2 = hb - 1;            int w2 = wb - 1;             if (h1 > h2 || w1 > w2) {                cout << 0 << '\n';                continue;            }             long long ans = pref[h2][w2]                          - pref[h1-1][w2]                          - pref[h2][w1-1]                          + pref[h1-1][w1-1];             cout << ans << '\n';        }    }     return 0;}